INSERT INTO _migration_589_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_matter_b003_002', 'topic_wassce_intsci_matter', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A metal block has a mass of 270 g and a volume of 100 cm³. Calculate the density of the metal.', 'calculation', NULL, NULL, '2.7 g/cm³', 'Density = mass ÷ volume = 270 g ÷ 100 cm³ = 2.7 g/cm³. Answer: the density of the metal is 2.7 g/cm³.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_matter_b003_003', 'topic_wassce_intsci_matter', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A student is given samples of candle wax, water and air to investigate.', 'structured', NULL, NULL, '(a) Solid, liquid and gas. (b) In a solid the particles are closely packed in fixed positions and can only vibrate, while in a gas the particles are far apart and move freely and rapidly in all directions.', '(a) Solid, liquid and gas. (b) In a solid the particles are closely packed in fixed positions and can only vibrate, while in a gas the particles are far apart and move freely and rapidly in all directions.', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_energy_b003_001', 'topic_wassce_intsci_energy', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Three resistors of 2 Ω, 3 Ω and 5 Ω are connected in series in a circuit. What is their total resistance?', 'multiple_choice', NULL, '["A. 10 Ω","B. 30 Ω","C. 5 Ω","D. 0.97 Ω"]', 'A', 'Resistors in series simply add: R = 2 + 3 + 5 = 10 Ω. (30 Ω comes from multiplying the values, and 0.97 Ω is the parallel combination 1 ÷ (½ + ⅓ + ⅕) — a common confusion between series and parallel rules.) Therefore the correct answer is A: 10 Ω.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, NULL),
('q_wisc_energy_b003_002', 'topic_wassce_intsci_energy', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Two identical lamps are connected in series in a circuit. If one lamp blows, the other lamp will', 'multiple_choice', NULL, '["A. shine brighter than before","B. go out because the circuit is now broken","C. stay on with the same brightness","D. become dimmer but remain lit"]', 'B', 'In a series circuit there is only one path for the current. A blown lamp creates a gap, so the current stops completely and the second lamp goes out. Only lamps in parallel are unaffected when one branch fails — a common misconception. Therefore the correct answer is B: go out because the circuit is now broken.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_energy_b003_003', 'topic_wassce_intsci_energy', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'An electric iron is rated at 1,000 W. Calculate the energy it consumes when used for 30 minutes, giving your answer in joules.', 'calculation', NULL, NULL, '1,800,000 J (1.8 × 10⁶ J)', 'Energy = power × time, with time in seconds: 30 minutes = 30 × 60 = 1,800 s. Energy = 1,000 W × 1,800 s = 1,800,000 J = 1.8 × 10⁶ J. Answer: the iron consumes 1.8 × 10⁶ J of energy.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_energy_b003_004', 'topic_wassce_intsci_energy', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A student sets up a simple circuit containing a battery, an ammeter and a resistor.', 'structured', NULL, NULL, '(a) The current flowing through a metallic conductor is directly proportional to the potential difference across its ends, provided temperature and other physical conditions remain constant (V = IR). (b) V = I × R = 2 A × 6 Ω = 12 V.', '(a) The current flowing through a metallic conductor is directly proportional to the potential difference across its ends, provided temperature and other physical conditions remain constant (V = IR). (b) V = I × R = 2 A × 6 Ω = 12 V.', 'medium', '4', '4', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_589_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_matter_b003_003_a', 'q_wisc_matter_b003_003', 'a', 'State the three states of matter.', '3', 'Solid, liquid and gas.', '1'),
('sqp_q_wisc_matter_b003_003_b', 'q_wisc_matter_b003_003', 'b', 'Describe how the arrangement and movement of particles differ between a solid and a gas.', '2', 'In a solid the particles are closely packed in fixed positions and can only vibrate, while in a gas the particles are far apart and move freely and rapidly in all directions.', '2'),
('sqp_q_wisc_energy_b003_004_a', 'q_wisc_energy_b003_004', 'a', 'State Ohm''s law.', '2', 'The current flowing through a metallic conductor is directly proportional to the potential difference across its ends, provided temperature and other physical conditions remain constant (V = IR).', '1'),
('sqp_q_wisc_energy_b003_004_b', 'q_wisc_energy_b003_004', 'b', 'The ammeter reads 2 A and the resistor has a resistance of 6 Ω. Calculate the potential difference across the resistor.', '2', 'V = I × R = 2 A × 6 Ω = 12 V.', '2');
INSERT INTO _migration_589_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_589_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_589_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_589_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_589_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_589_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_589_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_589_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_589_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_589_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_589_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_589_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 4 THEN 1 ELSE 0 END;
